import csv, math
from collections import defaultdict

def f(x):
    return float(x)

def pearson(xs, ys):
    n=len(xs)
    mx=sum(xs)/n
    my=sum(ys)/n
    num=sum((x-mx)*(y-my) for x,y in zip(xs,ys))
    denx=sum((x-mx)**2 for x in xs)
    deny=sum((y-my)**2 for y in ys)
    return num/math.sqrt(denx*deny)

rows=[]
with open('benchmark/data.csv', newline='', encoding='utf-8') as fp:
    r=csv.DictReader(fp)
    for row in r:
        row['petrol']=f(row['petrol_usd_liter'])
        row['diesel']=f(row['diesel_usd_liter'])
        row['lpg']=f(row['lpg_usd_liter'])
        row['brent']=f(row['brent_crude_usd'])
        row['tax']=f(row['tax_percentage'])
        rows.append(row)

# weekly global series
weekly=defaultdict(lambda: {'brent':None,'petrol':[],'diesel':[],'lpg':[]})
for r in rows:
    w=weekly[r['date']]
    w['petrol'].append(r['petrol'])
    w['diesel'].append(r['diesel'])
    w['lpg'].append(r['lpg'])
    if w['brent'] is None:
        w['brent']=r['brent']

w_dates=sorted(weekly)
w_br=[weekly[d]['brent'] for d in w_dates]
w_pet=[sum(weekly[d]['petrol'])/len(weekly[d]['petrol']) for d in w_dates]

# income x subsidy dampening + pass-through
# For each (income, subsidy in {High,Low}) compute avg petrol and brent-petrol corr using weekly means.

income_sub_rows=defaultdict(list)
for r in rows:
    if r['subsidy_level'] in ('High','Low'):
        income_sub_rows[(r['income_level'], r['subsidy_level'])].append(r)

avg_petrol= {}
for k, lst in income_sub_rows.items():
    avg_petrol[k]=sum(x['petrol'] for x in lst)/len(lst)

# dampening within income: (low-high)/low
income_damp={}
for inc in sorted(set(k[0] for k in avg_petrol)):
    lo=avg_petrol.get((inc,'Low'))
    hi=avg_petrol.get((inc,'High'))
    if lo and hi is not None:
        income_damp[inc]=(lo-hi)/lo*100.0

# pass-through corr by income+subsidy: build weekly avg petrol for that segment then correlate with brent
weekly_seg=defaultdict(list)
for r in rows:
    if r['subsidy_level'] in ('High','Low'):
        weekly_seg[(r['date'], r['income_level'], r['subsidy_level'])].append(r['petrol'])

seg_corr={}
for inc in sorted(set(r['income_level'] for r in rows)):
    for sub in ('High','Low'):
        xs=[]; ys=[]
        for d in w_dates:
            key=(d,inc,sub)
            if key in weekly_seg:
                xs.append(weekly[d]['brent'])
                ys.append(sum(weekly_seg[key])/len(weekly_seg[key]))
        if len(xs)>3:
            seg_corr[(inc,sub)]=pearson(xs,ys)

print('avg_petrol income/sub', avg_petrol)
print('income dampening %', income_damp)
print('seg corr', seg_corr)
PY

