*** Add File: generate_report.py
+import csv
+import html
+import json
+import math
+import os
+import statistics
+from collections import defaultdict
+
+
+DATA_PATH = os.path.join("benchmark", "data.csv")
+OUT_PATH = os.path.join("output", "final_report.html")
+
+
+def _to_float(value: str) -> float:
+    return float(value)
+
+
+def _year(date_str: str) -> int:
+    return int(date_str[:4])
+
+
+def _pearson(xs: list[float], ys: list[float]) -> float:
+    n = len(xs)
+    if n < 2:
+        return float("nan")
+    mean_x = sum(xs) / n
+    mean_y = sum(ys) / n
+    num = sum((x - mean_x) * (y - mean_y) for x, y in zip(xs, ys))
+    den_x = sum((x - mean_x) ** 2 for x in xs)
+    den_y = sum((y - mean_y) ** 2 for y in ys)
+    if den_x <= 0 or den_y <= 0:
+        return float("nan")
+    return num / math.sqrt(den_x * den_y)
+
+
+def _pct_changes(series: list[float]) -> list[float]:
+    out: list[float] = []
+    for i in range(1, len(series)):
+        prev = series[i - 1]
+        cur = series[i]
+        out.append((cur / prev - 1.0) if prev != 0 else float("nan"))
+    return out
+
+
+def _fmt_num(x: float, decimals: int = 2) -> str:
+    if x is None or (isinstance(x, float) and (math.isnan(x) or math.isinf(x))):
+        return "N/A"
+    return f"{x:.{decimals}f}"
+
+
+def _fmt_pct(x: float, decimals: int = 1) -> str:
+    if x is None or (isinstance(x, float) and (math.isnan(x) or math.isinf(x))):
+        return "N/A"
+    return f"{x*100:.{decimals}f}%"
+
+
+def load_rows(path: str) -> list[dict]:
+    rows: list[dict] = []
+    with open(path, newline="", encoding="utf-8") as fp:
+        reader = csv.DictReader(fp)
+        for r in reader:
+            rows.append(
+                {
+                    "date": r["date"],
+                    "year": _year(r["date"]),
+                    "country": r["country"],
+                    "region": r["region"],
+                    "income_level": r["income_level"],
+                    "subsidy_level": r["subsidy_level"],
+                    "petrol_usd_liter": _to_float(r["petrol_usd_liter"]),
+                    "diesel_usd_liter": _to_float(r["diesel_usd_liter"]),
+                    "lpg_usd_liter": _to_float(r["lpg_usd_liter"]),
+                    "brent_crude_usd": _to_float(r["brent_crude_usd"]),
+                    "tax_percentage": _to_float(r["tax_percentage"]),
+                }
+            )
+    return rows
+
+
+def compute_metrics(rows: list[dict]) -> dict:
+    fuels = ["petrol_usd_liter", "diesel_usd_liter", "lpg_usd_liter"]
+
+    # Weekly global means
+    weekly = defaultdict(lambda: {"brent": None, "petrol": [], "diesel": [], "lpg": []})
+    for r in rows:
+        w = weekly[r["date"]]
+        if w["brent"] is None:
+            w["brent"] = r["brent_crude_usd"]
+        w["petrol"].append(r["petrol_usd_liter"])
+        w["diesel"].append(r["diesel_usd_liter"])
+        w["lpg"].append(r["lpg_usd_liter"])
+
+    dates = sorted(weekly)
+    brent = [weekly[d]["brent"] for d in dates]
+    petrol = [sum(weekly[d]["petrol"]) / len(weekly[d]["petrol"]) for d in dates]
+    diesel = [sum(weekly[d]["diesel"]) / len(weekly[d]["diesel"]) for d in dates]
+    lpg = [sum(weekly[d]["lpg"]) / len(weekly[d]["lpg"]) for d in dates]
+
+    corr_petrol = _pearson(brent, petrol)
+    corr_diesel = _pearson(brent, diesel)
+
+    brent_pc = _pct_changes(brent)
+    petrol_pc = _pct_changes(petrol)
+    diesel_pc = _pct_changes(diesel)
+
+    # Volatility proxy: population std of weekly % changes
+    volatility = {
+        "brent_weekly_pct_std": statistics.pstdev(brent_pc),
+        "petrol_weekly_pct_std": statistics.pstdev(petrol_pc),
+        "diesel_weekly_pct_std": statistics.pstdev(diesel_pc),
+    }
+
+    # Extremes
+    min_br_i = min(range(len(brent)), key=lambda i: brent[i])
+    max_br_i = max(range(len(brent)), key=lambda i: brent[i])
+    min_pet_i = min(range(len(petrol)), key=lambda i: petrol[i])
+    max_pet_i = max(range(len(petrol)), key=lambda i: petrol[i])
+
+    extremes = {
+        "brent_min": {"date": dates[min_br_i], "value": brent[min_br_i]},
+        "brent_max": {"date": dates[max_br_i], "value": brent[max_br_i]},
+        "petrol_min": {"date": dates[min_pet_i], "value": petrol[min_pet_i]},
+        "petrol_max": {"date": dates[max_pet_i], "value": petrol[max_pet_i]},
+    }
+
+    # Top weekly Brent moves (absolute)
+    abs_moves = [(abs(brent_pc[i]), brent_pc[i], dates[i + 1]) for i in range(len(brent_pc))]
+    abs_moves.sort(reverse=True)
+    top_brent_moves = [
+        {"date": d, "pct_change": pc, "abs_pct_change": ab} for ab, pc, d in abs_moves[:10]
+    ]
+
+    # Global summary stats
+    summary = {}
+    for col in fuels:
+        vals = [r[col] for r in rows]
+        summary[col] = {"mean": sum(vals) / len(vals), "min": min(vals), "max": max(vals)}
+    brent_summary = {"mean": sum(brent) / len(brent), "min": min(brent), "max": max(brent)}
+
+    # Region-year average petrol and spread
+    regions = sorted(set(r["region"] for r in rows))
+    years = sorted(set(r["year"] for r in rows))
+    reg_year = defaultdict(list)
+    for r in rows:
+        reg_year[(r["region"], r["year"])].append(r["petrol_usd_liter"])
+    reg_year_avg = {(reg, y): sum(v) / len(v) for (reg, y), v in reg_year.items()}
+    regional_spread_yearly = {}
+    for y in years:
+        avs = [reg_year_avg[(reg, y)] for reg in regions]
+        regional_spread_yearly[y] = max(avs) - min(avs)
+
+    # Subsidy dampening: strict High vs Low (spec), plus other levels for context
+    by_sub = defaultdict(list)
+    for r in rows:
+        by_sub[r["subsidy_level"]].append(r["petrol_usd_liter"])
+    avg_petrol_by_subsidy = {k: sum(v) / len(v) for k, v in by_sub.items()}
+
+    dampening_high_vs_low = {}
+    for fuel_col in fuels:
+        by = defaultdict(list)
+        for r in rows:
+            if r["subsidy_level"] in ("High", "Low"):
+                by[r["subsidy_level"]].append(r[fuel_col])
+        hi = sum(by["High"]) / len(by["High"]) if by["High"] else float("nan")
+        lo = sum(by["Low"]) / len(by["Low"]) if by["Low"] else float("nan")
+        dampening_high_vs_low[fuel_col] = {
+            "high_avg": hi,
+            "low_avg": lo,
+            "pct_diff_high_vs_low": (lo - hi) / lo * 100.0 if lo else float("nan"),
+        }
+
+    # Pass-through (correlation) by subsidy level and by income x subsidy
+    subsidies = sorted(set(r["subsidy_level"] for r in rows))
+    weekly_sub = defaultdict(list)
+    for r in rows:
+        weekly_sub[(r["date"], r["subsidy_level"])].append(r["petrol_usd_liter"])
+    subsidy_pass_through = {}
+    for sub in subsidies:
+        xs = []
+        ys = []
+        for d in dates:
+            vals = weekly_sub.get((d, sub))
+            if vals:
+                xs.append(weekly[d]["brent"])
+                ys.append(sum(vals) / len(vals))
+        subsidy_pass_through[sub] = _pearson(xs, ys)
+
+    # Tax-to-price ratio by income level (dataset provides tax_percentage directly)
+    income_levels = sorted(set(r["income_level"] for r in rows))
+    income_tax = defaultdict(list)
+    for r in rows:
+        income_tax[r["income_level"]].append(r["tax_percentage"])
+    avg_tax_by_income = {k: sum(v) / len(v) for k, v in income_tax.items()}
+
+    # Average petrol by income x subsidy (High vs Low only) + within-income dampening
+    income_sub = defaultdict(list)
+    for r in rows:
+        if r["subsidy_level"] in ("High", "Low"):
+            income_sub[(r["income_level"], r["subsidy_level"])].append(r["petrol_usd_liter"])
+    avg_petrol_by_income_subsidy = {
+        (inc, sub): sum(v) / len(v) for (inc, sub), v in income_sub.items()
+    }
+    dampening_by_income = {}
+    for inc in income_levels:
+        lo = avg_petrol_by_income_subsidy.get((inc, "Low"))
+        hi = avg_petrol_by_income_subsidy.get((inc, "High"))
+        if lo is not None and hi is not None and lo != 0:
+            dampening_by_income[inc] = (lo - hi) / lo * 100.0
+
+    # Assemble chart payloads
+    chart_data = {
+        "weekly": {
+            "dates": dates,
+            "brent": brent,
+            "petrol": petrol,
+            "diesel": diesel,
+            "lpg": lpg,
+        },
+        "regions": regions,
+        "years": years,
+        "region_year_avg_petrol": {f"{reg}|{y}": reg_year_avg[(reg, y)] for reg in regions for y in years},
+        "avg_tax_by_income": avg_tax_by_income,
+        "avg_petrol_by_income_subsidy": {
+            f"{inc}|{sub}": avg_petrol_by_income_subsidy[(inc, sub)]
+            for inc in income_levels
+            for sub in ("High", "Low")
+            if (inc, sub) in avg_petrol_by_income_subsidy
+        },
+        "avg_petrol_by_subsidy": avg_petrol_by_subsidy,
+    }
+
+    return {
+        "n_rows": len(rows),
+        "n_countries": len(set(r["country"] for r in rows)),
+        "date_min": min(r["date"] for r in rows),
+        "date_max": max(r["date"] for r in rows),
+        "summary": summary,
+        "brent_summary": brent_summary,
+        "correlations": {
+            "brent_petrol_weekly_mean": corr_petrol,
+            "brent_diesel_weekly_mean": corr_diesel,
+        },
+        "volatility": volatility,
+        "extremes": extremes,
+        "top_brent_weekly_moves": top_brent_moves,
+        "regional_spread_yearly": regional_spread_yearly,
+        "avg_tax_by_income": avg_tax_by_income,
+        "dampening_high_vs_low": dampening_high_vs_low,
+        "dampening_by_income": dampening_by_income,
+        "subsidy_pass_through_corr": subsidy_pass_through,
+        "chart_data": chart_data,
+    }
+
+
+def render_html(metrics: dict) -> str:
+    title = "Global Fuel Price Trends & Policy Impact Analysis (2020–2026)"
+    subtitle = (
+        "Retail petrol/diesel/LPG prices across 84 countries (weekly), benchmarked to Brent Crude; "
+        "with subsidy/tax segmentation." 
+    )
+
+    chart_json = json.dumps(metrics["chart_data"])
