+    # KPI values (spec)
+    avg_petrol = metrics["summary"]["petrol_usd_liter"]["mean"]
+    corr_petrol = metrics["correlations"]["brent_petrol_weekly_mean"]
+    corr_diesel = metrics["correlations"]["brent_diesel_weekly_mean"]
