+    br_max = metrics["extremes"]["brent_max"]
+    pet_min = metrics["extremes"]["petrol_min"]
+    pet_max = metrics["extremes"]["petrol_max"]
+
+    # Key event windows (fixed calendar windows; values are computed from data via extremes/top moves)
+    # We avoid fabricating narrative-specific numbers and point to data-driven peaks.
+
+    html_out = f"""<!doctype html>
