+      font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Arial, "Apple Color Emoji", "Segoe UI Emoji";
+      background: radial-gradient(1200px 800px at 20% 0%, rgba(110,168,254,0.20), transparent 60%),
+                  radial-gradient(900px 700px at 85% 10%, rgba(115,226,167,0.15), transparent 55%),
+                  var(--bg);
+      color: var(--ink);
+    }}
+    header {{
