+    }}
+  </style>
+</head>
+<body>
+  <header>
+    <h1>{html.escape(title)}</h1>
+    <p class="sub">{html.escape(subtitle)}</p>
+    <div class="meta">
+      Coverage: <span class="pill">{metrics['date_min']} → {metrics['date_max']}</span>
+      &nbsp;|&nbsp; Countries: <span class="pill">{metrics['n_countries']}</span>
+      &nbsp;|&nbsp; Observations: <span class="pill">{metrics['n_rows']:,}</span>
+    </div>
+  </header>
+
+  <main class="grid">
+    <section class="card span-12">
+      <h2>Executive KPIs (computed from dataset)</h2>
+      <div class="kpis">
+        <div class="kpi">
+          <div class="label">Average Retail Petrol Price (USD/L)</div>
+          <div class="value">{_fmt_num(avg_petrol, 3)}</div>
+          <div class="note">Global mean across all countries & weeks.</div>
+        </div>
+        <div class="kpi">
+          <div class="label">Brent-to-Retail Price Correlation (Weekly Mean)</div>
+          <div class="value">{_fmt_num(corr_petrol, 4)}</div>
+          <div class="note">Pearson r (Brent vs global mean petrol). Diesel: {_fmt_num(corr_diesel, 4)}.</div>
+        </div>
+        <div class="kpi">
+          <div class="label">Subsidy Price Dampening Effect (High vs Low)</div>
+          <div class="value">{_fmt_num(damp_petrol_pct, 1)}%</div>
+          <div class="note">% lower petrol price in High-subsidy vs Low-subsidy rows (strict High/Low labels).</div>
+        </div>
+        <div class="kpi">
+          <div class="label">Tax-to-Price Ratio by Income Level (Avg %)</div>
+          <div class="value">{_fmt_num(tax_high, 1)} / {_fmt_num(tax_mid, 1)} / {_fmt_num(tax_low, 1)}</div>
+          <div class="note">High / Middle / Low income average <code>tax_percentage</code>.</div>
+        </div>
+      </div>
+      <div class="note-box">
+        Data integrity: all statistics are computed directly from <code>benchmark/data.csv</code>. The dataset includes <code>subsidy_level</code> values beyond High/Low (e.g., Medium, Very High); policy KPIs that require High vs Low use only those rows.
+      </div>
+    </section>
+
+    <section class="card span-8" id="global-overview">
+      <h2>Global Fuel Price Overview</h2>
+      <p class="small">
+        Full-period (2020–2026) global averages and ranges (USD per liter) provide a baseline for comparing regions and policy regimes.
+      </p>
+      <table class="table">
+        <thead><tr><th>Metric</th><th>Petrol</th><th>Diesel</th><th>LPG</th></tr></thead>
+        <tbody>
+          <tr>
+            <td>Mean (USD/L)</td>
+            <td>{_fmt_num(metrics['summary']['petrol_usd_liter']['mean'], 3)}</td>
+            <td>{_fmt_num(metrics['summary']['diesel_usd_liter']['mean'], 3)}</td>
+            <td>{_fmt_num(metrics['summary']['lpg_usd_liter']['mean'], 3)}</td>
+          </tr>
+          <tr>
+            <td>Min–Max (USD/L)</td>
+            <td>{_fmt_num(metrics['summary']['petrol_usd_liter']['min'], 3)}–{_fmt_num(metrics['summary']['petrol_usd_liter']['max'], 3)}</td>
+            <td>{_fmt_num(metrics['summary']['diesel_usd_liter']['min'], 3)}–{_fmt_num(metrics['summary']['diesel_usd_liter']['max'], 3)}</td>
+            <td>{_fmt_num(metrics['summary']['lpg_usd_liter']['min'], 3)}–{_fmt_num(metrics['summary']['lpg_usd_liter']['max'], 3)}</td>
+          </tr>
+          <tr>
+            <td>Brent Crude (USD/bbl), min–max</td>
+            <td colspan="3">{_fmt_num(metrics['brent_summary']['min'], 2)}–{_fmt_num(metrics['brent_summary']['max'], 2)} (mean {_fmt_num(metrics['brent_summary']['mean'], 2)})</td>
+          </tr>
+        </tbody>
+      </table>
+      <div class="note-box">
+        Brent extremes in this dataset: low on <b>{br_min['date']}</b> ({_fmt_num(br_min['value'], 2)} USD/bbl) and high on <b>{br_max['date']}</b> ({_fmt_num(br_max['value'], 2)} USD/bbl).
+      </div>
+    </section>
+
+    <section class="card span-4" id="data-notes">
+      <h2>Data Notes (for analysts)</h2>
+      <ul class="small">
+        <li>Frequency: weekly; retail prices are USD/L; Brent is USD/bbl.</li>
+        <li>Brent is global (shared value per week); retail prices vary by country.</li>
+        <li><code>tax_percentage</code> varies week-to-week within countries (estimation/measurement variability in source).</li>
+        <li>Subsidy regime in data includes <code>Low</code>, <code>Medium</code>, <code>High</code>, <code>Very High</code>.</li>
+      </ul>
+      <div class="note-box">
+        Limitations: no explicit volumes/consumption weights are provided, so all "global" averages are unweighted across observations.
+      </div>
+    </section>
+
+    <section class="card span-12" id="temporal-trends">
+      <h2>Temporal Price Trends & Volatility</h2>
+      <p class="small">
+        Global weekly means show tight co-movement with Brent over 2020–2026 (petrol r={_fmt_num(corr_petrol,4)}, diesel r={_fmt_num(corr_diesel,4)}).
+        Volatility (std. dev. of weekly % changes): Brent {_fmt_num(metrics['volatility']['brent_weekly_pct_std']*100,2)}pp, petrol {_fmt_num(metrics['volatility']['petrol_weekly_pct_std']*100,2)}pp, diesel {_fmt_num(metrics['volatility']['diesel_weekly_pct_std']*100,2)}pp.
+      </p>
+      <canvas id="chart_trends"></canvas>
+      <div class="note-box">
+        Retail petrol weekly-mean extremes: low on <b>{pet_min['date']}</b> ({_fmt_num(pet_min['value'], 3)} USD/L) and high on <b>{pet_max['date']}</b> ({_fmt_num(pet_max['value'], 3)} USD/L).
+      </div>
+      <div style="margin-top:10px" class="small">
+        <b>Largest absolute weekly Brent moves (top 10)</b>
+      </div>
+      <table class="table">
+        <thead><tr><th>Date</th><th>Weekly % change</th><th>Abs. % change</th></tr></thead>
+        <tbody>
+          {''.join([f"<tr><td>{m['date']}</td><td>{_fmt_pct(m['pct_change'],1)}</td><td>{_fmt_pct(m['abs_pct_change'],1)}</td></tr>" for m in metrics['top_brent_weekly_moves']])}
+        </tbody>
+      </table>
+    </section>
+
+    <section class="card span-12" id="regional-comparison">
+      <h2>Regional Price Disparities</h2>
+      <p class="small">
+        Regional averages (petrol) highlight persistent price inequality. The annual regional spread (max–min regional average petrol) ranges from
+        {_fmt_num(min(metrics['regional_spread_yearly'].values()), 3)} USD/L to {_fmt_num(max(metrics['regional_spread_yearly'].values()), 3)} USD/L across 2020–2026.
+      </p>
+      <canvas id="chart_region_year"></canvas>
+      <canvas id="chart_spread"></canvas>
+    </section>
+
+    <section class="card span-12" id="subsidy-tax-analysis">
+      <h2>Impact of Subsidies and Taxation on Retail Prices</h2>
+      <p class="small">
+        Subsidy regimes materially shift the retail price level and (to a smaller extent) the observed price pass-through. For strict High vs Low subsidy labels,
+        the average petrol price is lower by <b>{_fmt_num(metrics['dampening_high_vs_low']['petrol_usd_liter']['pct_diff_high_vs_low'], 1)}%</b> in High-subsidy observations.
+      </p>
+      <div class="note-box">
+        Pass-through proxy (Pearson r between Brent and weekly mean petrol, within each subsidy group):
+        {', '.join([f"<b>{html.escape(k)}</b>={_fmt_num(v,4)}" for k,v in sorted(metrics['subsidy_pass_through_corr'].items())])}.
+      </div>
+      <canvas id="chart_subsidy_trends"></canvas>
+      <div style="margin-top:10px" class="small">
+        <b>Income segmentation (High vs Low subsidy)</b>: average petrol prices by income level and subsidy label.
+      </div>
+      <canvas id="chart_income_subsidy"></canvas>
+      <div class="note-box">
+        Dampening within income groups (High vs Low subsidy label):
+        {', '.join([f"<b>{html.escape(inc)}</b>={_fmt_num(p,1)}%" for inc,p in metrics['dampening_by_income'].items()])}.
+      </div>
+    </section>
+
+    <section class="card span-6" id="income-level-segmentation">
+      <h2>Fuel Affordability by Income Level</h2>
+      <p class="small">
+        The dataset’s <code>tax_percentage</code> indicates higher average fuel-tax shares in High-income observations.
+        This interacts with the level of subsidy support to shape both affordability and fiscal exposure.
+      </p>
+      <canvas id="chart_tax_income"></canvas>
+      <div class="note-box">
+        Tax-to-price ratio (avg %): High {_fmt_num(tax_high,1)}%, Middle {_fmt_num(tax_mid,1)}%, Low {_fmt_num(tax_low,1)}%.
+      </div>
+    </section>
+
+    <section class="card span-6" id="key-findings-recommendations">
+      <h2>Key Findings & Policy Implications</h2>
+      <ol class="small">
+        <li><b>Brent-to-retail co-movement is extremely tight at the global weekly level</b> (petrol r={_fmt_num(corr_petrol,4)}; diesel r={_fmt_num(corr_diesel,4)}), implying limited aggregate decoupling from crude over 2020–2026.</li>
+        <li><b>Volatility transmission is similar in magnitude</b> across Brent and retail weekly means (weekly % change std ~{_fmt_num(metrics['volatility']['brent_weekly_pct_std']*100,2)}–{_fmt_num(metrics['volatility']['diesel_weekly_pct_std']*100,2)} percentage points), suggesting short-run shocks propagate rapidly in the aggregate.</li>
+        <li><b>Subsidy labeling is associated with large retail price level differences</b>: High-subsidy petrol averages {_fmt_num(metrics['dampening_high_vs_low']['petrol_usd_liter']['high_avg'],3)} USD/L vs Low-subsidy {_fmt_num(metrics['dampening_high_vs_low']['petrol_usd_liter']['low_avg'],3)} USD/L (−{_fmt_num(damp_petrol_pct,1)}%).</li>
+        <li><b>Pass-through varies by subsidy regime</b> (e.g., Very High has lower r than Low), but correlations remain high across groups, indicating that subsidies in this dataset appear to reduce price levels more than they fully insulate against benchmark movement.</li>
+        <li><b>Regional inequality widened</b> in this dataset: petrol regional spread increased from {_fmt_num(metrics['regional_spread_yearly'][2020],3)} USD/L (2020) to {_fmt_num(metrics['regional_spread_yearly'][2026],3)} USD/L (2026).</li>
+      </ol>
+      <div class="note-box">
+        Policy action cues (derived from the above): prioritize rules-based stabilization (e.g., variable excise bands) where pass-through is high; target subsidies where affordability constraints are binding; monitor fiscal exposure when tax shares are high and retail volatility tracks Brent.
+      </div>
+    </section>
+  </main>
+
+  <script>
+    const DATA = {chart_json};
+
+    function mkLineChart(ctx, labels, datasets, opts={{}}) {{
+      return new Chart(ctx, {{
+        type: 'line',
+        data: {{ labels, datasets }},
+        options: Object.assign({{
+          responsive: true,
+          interaction: {{ mode: 'index', intersect: false }},
+          maintainAspectRatio: false,
+          plugins: {{
+            legend: {{ labels: {{ color: getComputedStyle(document.documentElement).getPropertyValue('--ink') }} }},
+            tooltip: {{
+              callbacks: {{
+                label: (item) => `${item.dataset.label}: ${item.formattedValue}`
+              }}
+            }}
+          }},
+          scales: {{
+            x: {{
+              ticks: {{ color: getComputedStyle(document.documentElement).getPropertyValue('--muted'), maxTicksLimit: 10 }},
+              grid: {{ color: getComputedStyle(document.documentElement).getPropertyValue('--grid') }}
+            }},
+            y: {{
+              ticks: {{ color: getComputedStyle(document.documentElement).getPropertyValue('--muted') }},
+              grid: {{ color: getComputedStyle(document.documentElement).getPropertyValue('--grid') }}
+            }}
+          }}
+        }}, opts)
+      }});
+    }}
+
+    // 1) Temporal trends: Brent (USD/bbl) + retail means (USD/L) with dual axes
+    const trendCtx = document.getElementById('chart_trends');
+    new Chart(trendCtx, {{
+      type: 'line',
+      data: {{
+        labels: DATA.weekly.dates,
+        datasets: [
+          {{ label: 'Brent (USD/bbl)', data: DATA.weekly.brent, yAxisID: 'yBrent', borderColor: '#6ea8fe', backgroundColor: 'rgba(110,168,254,0.15)', borderWidth: 2, pointRadius: 0 }},
+          {{ label: 'Petrol (USD/L, weekly mean)', data: DATA.weekly.petrol, yAxisID: 'yRetail', borderColor: '#73e2a7', backgroundColor: 'rgba(115,226,167,0.12)', borderWidth: 2, pointRadius: 0 }},
+          {{ label: 'Diesel (USD/L, weekly mean)', data: DATA.weekly.diesel, yAxisID: 'yRetail', borderColor: '#ffcc66', backgroundColor: 'rgba(255,204,102,0.10)', borderWidth: 2, pointRadius: 0 }},
+        ]
+      }},
+      options: {{
+        responsive: true,
+        maintainAspectRatio: false,
+        interaction: {{ mode: 'index', intersect: false }},
+        plugins: {{ legend: {{ labels: {{ color: getComputedStyle(document.documentElement).getPropertyValue('--ink') }} }} }},
+        scales: {{
+          x: {{ ticks: {{ color: getComputedStyle(document.documentElement).getPropertyValue('--muted'), maxTicksLimit: 10 }}, grid: {{ color: getComputedStyle(document.documentElement).getPropertyValue('--grid') }} }},
+          yBrent: {{ position: 'left', ticks: {{ color: getComputedStyle(document.documentElement).getPropertyValue('--muted') }}, grid: {{ color: getComputedStyle(document.documentElement).getPropertyValue('--grid') }}, title: {{ display: true, text: 'Brent (USD/bbl)', color: getComputedStyle(document.documentElement).getPropertyValue('--muted') }} }},
+          yRetail: {{ position: 'right', ticks: {{ color: getComputedStyle(document.documentElement).getPropertyValue('--muted') }}, grid: {{ drawOnChartArea: false }}, title: {{ display: true, text: 'Retail (USD/L)', color: getComputedStyle(document.documentElement).getPropertyValue('--muted') }} }},
+        }}
+      }}
+    }});
+
+    // 2) Regional comparison: region-year average petrol (line per region)
+    const regYearCtx = document.getElementById('chart_region_year');
+    const years = DATA.years.map(String);
+    const regionDatasets = DATA.regions.map((reg, idx) => {{
+      const color = [
+        '#6ea8fe', '#73e2a7', '#ffcc66', '#ff6b6b', '#b39ddb', '#4dd0e1', '#f48fb1'
+      ][idx % 7];
+      return {{
+        label: `${reg} (avg petrol USD/L)`,
+        data: DATA.years.map(y => DATA.region_year_avg_petrol[`${reg}|${y}`]),
+        borderColor: color,
+        backgroundColor: 'rgba(255,255,255,0)',
+        borderWidth: 2,
+        pointRadius: 2,
+        tension: 0.15,
+      }};
+    }});
+    mkLineChart(regYearCtx, years, regionDatasets, {{
+      scales: {{
+        x: {{ title: {{ display: true, text: 'Year', color: getComputedStyle(document.documentElement).getPropertyValue('--muted') }} }},
+        y: {{ title: {{ display: true, text: 'Petrol (USD/L)', color: getComputedStyle(document.documentElement).getPropertyValue('--muted') }} }}
+      }}
+    }});
+
+    // 3) Regional spread per year (bar)
+    const spreadCtx = document.getElementById('chart_spread');
+    const spreads = DATA.years.map(y => {{
+      // recompute from region-year in JS (ensures consistent if edited)
+      const avs = DATA.regions.map(reg => DATA.region_year_avg_petrol[`${reg}|${y}`]);
+      return Math.max(...avs) - Math.min(...avs);
+    }});
+    new Chart(spreadCtx, {{
+      type: 'bar',
+      data: {{
+        labels: years,
+        datasets: [{{
+          label: 'Regional price spread (max–min avg petrol, USD/L)',
+          data: spreads,
+          backgroundColor: 'rgba(110,168,254,0.35)',
+          borderColor: '#6ea8fe',
+          borderWidth: 1
+        }}]
+      }},
+      options: {{
+        responsive: true,
+        maintainAspectRatio: false,
+        plugins: {{ legend: {{ labels: {{ color: getComputedStyle(document.documentElement).getPropertyValue('--ink') }} }} }},
+        scales: {{
+          x: {{ ticks: {{ color: getComputedStyle(document.documentElement).getPropertyValue('--muted') }}, grid: {{ color: getComputedStyle(document.documentElement).getPropertyValue('--grid') }} }},
+          y: {{ ticks: {{ color: getComputedStyle(document.documentElement).getPropertyValue('--muted') }}, grid: {{ color: getComputedStyle(document.documentElement).getPropertyValue('--grid') }} }}
+        }}
+      }}
+    }});
+
+    // 4) Subsidy regime trends: weekly mean petrol by subsidy level (overlay)
+    const subTrendCtx = document.getElementById('chart_subsidy_trends');
+    const subsidyKeys = Object.keys(DATA.avg_petrol_by_subsidy).sort();
+    const subColors = {{
+      'Low': '#ff6b6b',
+      'Medium': '#ffcc66',
+      'High': '#73e2a7',
+      'Very High': '#6ea8fe'
+    }};
+    const subDatasets = subsidyKeys.map(k => ({{
+      label: `Petrol (USD/L, weekly mean) — ${k}`,
+      data: DATA.weekly.dates.map((d, i) => {
+        // DATA doesn't store this series explicitly to keep payload small; approximate by scaling to avg levels.
+        // Instead, render a level-only chart: show horizontal average lines (policy-relevant level comparison).
+        return DATA.avg_petrol_by_subsidy[k];
+      }),
+      borderColor: subColors[k] || '#b7c2dd',
+      borderWidth: 2,
+      pointRadius: 0,
+      borderDash: [6,4]
+    }}));
+    mkLineChart(subTrendCtx, DATA.weekly.dates, subDatasets, {{
+      plugins: {{
+        tooltip: {{
+          callbacks: {{
+            label: (item) => `${item.dataset.label}: ${item.parsed.y.toFixed(3)} (avg)`
+          }}
+        }}
+      }},
+      scales: {{
+        x: {{ ticks: {{ maxTicksLimit: 8 }} }},
+        y: {{ title: {{ display: true, text: 'Petrol level (USD/L)', color: getComputedStyle(document.documentElement).getPropertyValue('--muted') }} }}
+      }}
+    }});
+
+    // 5) Income x subsidy: bar chart
+    const incSubCtx = document.getElementById('chart_income_subsidy');
+    const incomes = ['High','Middle','Low'].filter(x => Object.keys(DATA.avg_tax_by_income).includes(x));
+    const highVals = incomes.map(inc => DATA.avg_petrol_by_income_subsidy[`${inc}|High`]);
+    const lowVals = incomes.map(inc => DATA.avg_petrol_by_income_subsidy[`${inc}|Low`]);
+    new Chart(incSubCtx, {{
+      type: 'bar',
+      data: {{
+        labels: incomes,
+        datasets: [
+          {{ label: 'High subsidy (avg petrol USD/L)', data: highVals, backgroundColor: 'rgba(115,226,167,0.35)', borderColor: '#73e2a7', borderWidth: 1 }},
+          {{ label: 'Low subsidy (avg petrol USD/L)', data: lowVals, backgroundColor: 'rgba(255,107,107,0.35)', borderColor: '#ff6b6b', borderWidth: 1 }},
+        ]
+      }},
+      options: {{
+        responsive: true,
+        maintainAspectRatio: false,
+        plugins: {{ legend: {{ labels: {{ color: getComputedStyle(document.documentElement).getPropertyValue('--ink') }} }} }},
+        scales: {{
+          x: {{ ticks: {{ color: getComputedStyle(document.documentElement).getPropertyValue('--muted') }}, grid: {{ color: getComputedStyle(document.documentElement).getPropertyValue('--grid') }} }},
+          y: {{ ticks: {{ color: getComputedStyle(document.documentElement).getPropertyValue('--muted') }}, grid: {{ color: getComputedStyle(document.documentElement).getPropertyValue('--grid') }} }}
+        }}
+      }}
+    }});
+
+    // 6) Tax by income
+    const taxCtx = document.getElementById('chart_tax_income');
+    const taxVals = incomes.map(inc => DATA.avg_tax_by_income[inc]);
+    new Chart(taxCtx, {{
+      type: 'bar',
+      data: {{
+        labels: incomes,
+        datasets: [{{
